void Menu_Login::VisualControlDoAction( IVisualControl* visual_control, int action_id )
{

	switch ( action_id ) 
	{
	case action_back: 
		{
			Transition_Start( transition_hide, action_back_trans );
		}
		break; 
	case action_back_trans: 
		{
			if (Menu_Score::BackGoesToHighScoreList())
				GetParent()->SubMenu_Change( "Menu_HighScoresLevelList" );
			else
				GetParent()->SubMenu_Change( "Menu_HighScore" );
			changeStatusText( LIS_WaitForLoginButton );
		}
		break; 
	case action_remember: 
		{
			m_rememberCheck = !m_rememberCheck; 
			if ( m_rememberCheck ) 
				m_rememberMe->SetAnimations( m_sprite, 3, k_button_remember_checked, k_button_remember_blink_checked, k_button_remember_checked_pressed);
			else
				m_rememberMe->SetAnimations( m_sprite, 3, k_button_remember_notchecked, k_button_remember_blink_notchecked, k_button_remember_notchecked_pressed );
		}
		break;

	//case action_login:
	//	{
	//		Transition_Start( transition_hide, action_login_trans );
	//	}
	//	break;
	case action_login:
		{	
			changeStatusText( LIS_Logging );

			CXPlayerManager::GetInstance()->Login( m_username, m_password );

#if defined(OS_WIN32) || defined(OS_LINUX)
			((MenuMain* )GetParent())->GetMenuScore()->SetInputData( MenuScoreTop10, 12, tmp_name, tmp_score, tmp_pos, 1, "" );
			((MenuMain* )GetParent())->GetMenuScore()->SetInputData( MenuScoreMyRank, 12, tmp_name1, tmp_score, tmp_pos, 1, "" );
			GetParent()->SubMenu_Change( "Menu_Score" );
#endif
		}
		break;
	}
}

